72	HcclResult InsCollAlgBase::FastLaunchSaveCtxTwoTemplate(
73	    const OpParam& param, const u32 threadNum, const u32 ccuKernelNum, const std::vector<ThreadHandle>& threads,
74	    const std::vector<u32>& ccuKernelNumList, const std::vector<std::vector<CcuKernelSubmitInfo>>& submitInfosList,
75	    u32 notifyNumOnMainThread) const
76	{
77	    if (param.opMode == OpMode::OFFLOAD) {
78	        return HCCL_SUCCESS;
79	    }
80	    u64 size = CcuFastLaunchCtx::GetCtxSize(threadNum, ccuKernelNum);
81	    // 申请ctx
82	    void* ctxPtr = nullptr;
83	    HCCL_INFO("[InsCollAlgBase][FastLaunchSaveCtxTwoTemplate] Tag[%s], size[%llu]", param.fastLaunchTag, size);
84	    CHK_RET(HcclEngineCtxCreate(param.hcclComm, param.fastLaunchTag, CommEngine::COMM_ENGINE_CCU, size, &ctxPtr));
85	
