89	    HCCL_INFO("[InsCollAlgBase][FastLaunchSaveCtxTwoTemplate] algName[%s]", ccuFastLaunchCtx->algName);
90	
91	    // 2 thread
92	    ccuFastLaunchCtx->threadNum = threadNum;
93	    ccuFastLaunchCtx->notifyNumOnMainThread = notifyNumOnMainThread;
94	    ThreadHandle* threadHandles = ccuFastLaunchCtx->GetThreadHandlePtr();
95	    for (u32 i = 0; i < threadNum; i++) {
96	        threadHandles[i] = threads[i];
97	    }
98	
99	    // 3.1 ccu kernel数量
100	    for (u32 templateIdx = 0; templateIdx < ccuKernelNumList.size(); templateIdx++) {
101	        // 4次调用template.KernelRun下发kernel
102	        ccuFastLaunchCtx->ccuKernelNum[templateIdx] = ccuKernelNumList[templateIdx];
103	    }
104	    // 3.2 所有ccu kernel submitInfo打平放入数组
105	    constexpr u32 INTRA_0 = 0, INTER_1 = 1, INTER_0 = 2, INTRA_1 = 3;
106	    constexpr u32 INTRA = 0, INTER = 1;
107	    constexpr u32 kernelParallelNum = 4;
108	    u32 kernelIdx = 0;
109	    CcuKernelSubmitInfo* kernelSubmitInfos = ccuFastLaunchCtx->GetCcuKernelSubmitInfoPtr();
110	    // 2个template实例，submitInfosList只有2份
111	    for (u32 i = 0; i < ccuKernelNumList[INTRA_0]; i++) {
112	        kernelSubmitInfos[kernelIdx++] = submitInfosList[INTRA][i];
113	    }
114	    for (u32 i = 0; i < ccuKernelNumList[INTER_1]; i++) {
115	        kernelSubmitInfos[kernelIdx++] = submitInfosList[INTER][i];
116	    }
117	    if (ccuKernelNumList.size() == kernelParallelNum) {
118	        for (u32 i = ccuKernelNumList[INTER_1]; i < ccuKernelNumList[INTER_0] + ccuKernelNumList[INTER_1]; i++) {
119	            kernelSubmitInfos[kernelIdx++] = submitInfosList[INTER][i];
120	        }
