69	template <
70	    typename AlgTopoMatch, typename InsAlgTemplate0, typename InsAlgTemplate1, typename InsAlgTemplate2,
71	    typename InsAlgTemplate3>
72	HcclResult
73	InsV2AllReduceSequenceExecutor<AlgTopoMatch, InsAlgTemplate0, InsAlgTemplate1, InsAlgTemplate2, InsAlgTemplate3>::
74	    CalcRes(
75	        HcclComm comm, const OpParam& param, const TopoInfoWithNetLayerDetails* topoInfo,
76	        const AlgHierarchyInfoForAllLevel& algHierarchyInfo, AlgResourceRequest& resourceRequest)
77	{
78	    // 初始化一些基本成员变量
79	    InitCommInfo(param, topoInfo, algHierarchyInfo);
80	
81	    rankSizeLevel0_ = algHierarchyInfo.infos[0].size();
82	    rankSizeLevel1_ = algHierarchyInfo.infos[1].size();
83	
84	    std::shared_ptr<InsAlgTemplate0> reduceScatterMesh1DTempAlg
85	        = std::make_shared<InsAlgTemplate0>(param, myRank_, algHierarchyInfo.infos[0]);
86	    std::shared_ptr<InsAlgTemplate1> reduceScatterMesh1dDpuTempAlg
87	        = std::make_shared<InsAlgTemplate1>(param, myRank_, algHierarchyInfo.infos[1]);
88	    std::shared_ptr<InsAlgTemplate2> allGatherNhrDPUTempAlg
89	        = std::make_shared<InsAlgTemplate2>(param, myRank_, algHierarchyInfo.infos[1]);
90	    std::shared_ptr<InsAlgTemplate3> allGatherMesh1DTempAlg
91	        = std::make_shared<InsAlgTemplate3>(param, myRank_, algHierarchyInfo.infos[0]);
92	
93	    AlgResourceRequest resReqReduceScatterMesh1D;
94	    AlgResourceRequest resReqReduceScatterMesh1dDpu;
95	    AlgResourceRequest resReqAllGatherNhrDPU;
96	    AlgResourceRequest resReqAllGatherMesh1D;
97	    CHK_RET(reduceScatterMesh1DTempAlg->CalcRes(comm, param, topoInfo, resReqReduceScatterMesh1D));
98	    CHK_RET(reduceScatterMesh1dDpuTempAlg->CalcRes(comm, param, topoInfo, resReqReduceScatterMesh1dDpu));
99	    CHK_RET(allGatherNhrDPUTempAlg->CalcRes(comm, param, topoInfo, resReqAllGatherNhrDPU));
100	    CHK_RET(allGatherMesh1DTempAlg->CalcRes(comm, param, topoInfo, resReqAllGatherMesh1D));
101	
102	    // step1、2、3、4为串行，因此slaveThread和对应notify可以复用
103	    resourceRequest.slaveThreadNum
104	        = std::max(resReqReduceScatterMesh1D.slaveThreadNum, resReqReduceScatterMesh1dDpu.slaveThreadNum);
105	    resourceRequest.notifyNumPerThread.clear();
106	    resourceRequest.notifyNumPerThread.resize(resourceRequest.slaveThreadNum);
107	    for (u32 i = 0; i < resourceRequest.slaveThreadNum; ++i) {
108	        if (i < resReqReduceScatterMesh1D.notifyNumPerThread.size()) {
109	            resourceRequest.notifyNumPerThread[i]
110	                = std::max(resourceRequest.notifyNumPerThread[i], resReqReduceScatterMesh1D.notifyNumPerThread[i]);
111	        }
112	        if (i < resReqReduceScatterMesh1dDpu.notifyNumPerThread.size()) {
113	            resourceRequest.notifyNumPerThread[i]
114	                = std::max(resourceRequest.notifyNumPerThread[i], resReqReduceScatterMesh1dDpu.notifyNumPerThread[i]);
115	        }
116	    }
117	    resourceRequest.notifyNumOnMainThread
118	        = std::max(resReqReduceScatterMesh1D.notifyNumOnMainThread, resReqReduceScatterMesh1dDpu.notifyNumOnMainThread);
119	
120	    resourceRequest.channels = {resReqReduceScatterMesh1D.channels[0], resReqReduceScatterMesh1dDpu.channels[0]};
121	    return HCCL_SUCCESS;
122	}
