124	template <
125	    typename AlgTopoMatch, typename InsAlgTemplate0, typename InsAlgTemplate1, typename InsAlgTemplate2,
126	    typename InsAlgTemplate3>
127	HcclResult
128	InsV2AllReduceSequenceExecutor<AlgTopoMatch, InsAlgTemplate0, InsAlgTemplate1, InsAlgTemplate2, InsAlgTemplate3>::
129	    Orchestrate(const OpParam& param, const AlgResourceCtxSerializable& resCtx)
130	{
131	    HCCL_INFO("[InsV2AllReduceSequenceExecutor][Orchestrate] Orchestrate Start");
132	    // 参数填充
133	    myRank_ = resCtx.topoInfo.userRank;
134	    rankSize_ = resCtx.topoInfo.userRankSize;
135	
136	    dataTypeSize_ = HCCL_SIZE_TABLE[param.DataDes.dataType];
137	    dataSize_ = dataCount_ * dataTypeSize_;
138	    dataCount_ = param.DataDes.count;
139	    dataType_ = param.DataDes.dataType;
140	    reduceOp_ = param.reduceType;
141	    algHierarchyInfo_ = resCtx.algHierarchyInfo;
142	    threads_ = resCtx.threads;
143	
144	    rankIdxLevel0_ = myRank_ % algHierarchyInfo_.infos[0][0].size();
145	    rankIdxLevel1_ = myRank_ / algHierarchyInfo_.infos[0][0].size();
146	
147	    rankSizeLevel0_ = algHierarchyInfo_.infos[0][0].size();
148	    rankSizeLevel1_ = algHierarchyInfo_.infos[1][0].size();
149	    CHK_RET(RestoreChannelMap(resCtx, remoteRankToChannelInfo_));
150	
151	    // 算法展开
152	    HcclResult ret = OrchestrateLoop(param, resCtx);
153	    CHK_PRT_RET(
154	        ret != HCCL_SUCCESS,
155	        HCCL_ERROR(
156	            "[InsV2AllReduceSequenceExecutor][Orchestrate]errNo[0x%016llx] AllReduce executor kernel run failed",
157	            HCCL_ERROR_CODE(ret)),
158	        ret);
159	    return HCCL_SUCCESS;
160	}
