162	template <
163	    typename AlgTopoMatch, typename InsAlgTemplate0, typename InsAlgTemplate1, typename InsAlgTemplate2,
164	    typename InsAlgTemplate3>
165	HcclResult
166	InsV2AllReduceSequenceExecutor<AlgTopoMatch, InsAlgTemplate0, InsAlgTemplate1, InsAlgTemplate2, InsAlgTemplate3>::
167	    OrchestrateLoop(const OpParam& param, const AlgResourceCtxSerializable& resCtx)
168	{
169	    HCCL_INFO("[InsV2AllReduceSequenceExecutor][OrchestrateLoop] Start");
170	    // 将ccl-buffer分成ccl-in和ccl-out 2部分区分使用
171	    void* cclInAddr = resCtx.cclMem.addr;
172	    HcclMem cclInMem = {resCtx.cclMem.type, cclInAddr, resCtx.cclMem.size / 2};
173	    void* cclOutAddr = static_cast<void*>(static_cast<s8*>(resCtx.cclMem.addr) + resCtx.cclMem.size / 2);
174	    HcclMem cclOutMem = {resCtx.cclMem.type, cclOutAddr, resCtx.cclMem.size / 2};
175	
176	    // 声明框内ReduceScatterMesh1D的templateargs
177	    TemplateDataParams tempAlgParamsStepOne;
178	    tempAlgParamsStepOne.buffInfo.inputPtr = param.inputPtr;
179	    tempAlgParamsStepOne.buffInfo.outputPtr = cclOutMem.addr;
180	    tempAlgParamsStepOne.buffInfo.hcclBuff = cclInMem;
181	
182	    // 构建框内ReduceScatterMesh1D的template
183	    std::shared_ptr<InsAlgTemplate0> algTemplateStepOne
184	        = std::make_shared<InsAlgTemplate0>(param, myRank_, algHierarchyInfo_.infos[0]);
185	
186	    // 声明框间ReduceScatterMesh1dDpu的templateargs
187	    TemplateDataParams tempAlgParamsStepTwo;
188	    tempAlgParamsStepTwo.buffInfo.inputPtr = cclOutMem.addr;
189	    tempAlgParamsStepTwo.buffInfo.outputPtr = cclOutMem.addr;
190	    tempAlgParamsStepTwo.buffInfo.hcclBuff = cclInMem;
191	
192	    // 构建框间ReduceScatterMesh1dDpu的template
193	    std::shared_ptr<InsAlgTemplate1> algTemplateStepTwo
194	        = std::make_shared<InsAlgTemplate1>(param, myRank_, algHierarchyInfo_.infos[1]);
195	
196	    // 声明框间AllGatherNhr的templateargs，ccl-out搬运到ccl-out
197	    TemplateDataParams tempAlgParamsStepThree;
198	    tempAlgParamsStepThree.buffInfo.inputPtr = cclOutMem.addr;
199	    tempAlgParamsStepThree.buffInfo.outputPtr = cclOutMem.addr;
200	    tempAlgParamsStepThree.buffInfo.hcclBuff = cclInMem;
201	
202	    // 构建框间AllGatherNhrDPU的template
203	    std::shared_ptr<InsAlgTemplate2> algTemplateStepThree
204	        = std::make_shared<InsAlgTemplate2>(param, myRank_, algHierarchyInfo_.infos[1]);
205	
206	    // 声明框内AllGatherMesh1D的templateargs，ccl-out搬运到user-out
207	    TemplateDataParams tempAlgParamsStepFour;
208	    tempAlgParamsStepFour.buffInfo.inputPtr = cclOutMem.addr;
209	    tempAlgParamsStepFour.buffInfo.outputPtr = param.outputPtr;
210	    tempAlgParamsStepFour.buffInfo.hcclBuff = cclInMem;
211	
212	    // 构建框内AllGatherMesh1D的template
213	    std::shared_ptr<InsAlgTemplate3> algTemplateStepFour
214	        = std::make_shared<InsAlgTemplate3>(param, myRank_, algHierarchyInfo_.infos[0]);
215	
216	    // 构造框内ReduceScatterMesh1D的template资源
217	    TemplateResource templateResourceReduceScatterMesh1D;
218	    templateResourceReduceScatterMesh1D.channels = remoteRankToChannelInfo_[0];
219	    templateResourceReduceScatterMesh1D.threads = resCtx.threads;
220	    templateResourceReduceScatterMesh1D.npu2DpuShmemPtr = resCtx.npu2DpuShmemPtr;
221	    templateResourceReduceScatterMesh1D.dpu2NpuShmemPtr = resCtx.dpu2NpuShmemPtr;
222	    // 构造框间ReduceScatterMesh1dDpu的template资源
223	    TemplateResource templateResourceReduceScatterMesh1dDpu;
224	    templateResourceReduceScatterMesh1dDpu.channels = remoteRankToChannelInfo_[1];
225	    templateResourceReduceScatterMesh1dDpu.threads = resCtx.threads;
226	    templateResourceReduceScatterMesh1dDpu.npu2DpuShmemPtr = resCtx.npu2DpuShmemPtr;
227	    templateResourceReduceScatterMesh1dDpu.dpu2NpuShmemPtr = resCtx.dpu2NpuShmemPtr;
228	    // 构造框间AllGatherNhrDPU的template资源
229	    TemplateResource templateResourceAllGatherNhrDPU;
230	    templateResourceAllGatherNhrDPU.channels = remoteRankToChannelInfo_[1];
231	    templateResourceAllGatherNhrDPU.threads = resCtx.threads;
232	    templateResourceAllGatherNhrDPU.npu2DpuShmemPtr = resCtx.npu2DpuShmemPtr;
233	    templateResourceAllGatherNhrDPU.dpu2NpuShmemPtr = resCtx.dpu2NpuShmemPtr;
234	    // 构造框内AllGatherMesh1D的template资源
235	    TemplateResource templateResourceAllGatherMesh1D;
236	    templateResourceAllGatherMesh1D.channels = remoteRankToChannelInfo_[0];
237	    templateResourceAllGatherMesh1D.threads = resCtx.threads;
238	    templateResourceAllGatherMesh1D.npu2DpuShmemPtr = resCtx.npu2DpuShmemPtr;
239	    templateResourceAllGatherMesh1D.dpu2NpuShmemPtr = resCtx.dpu2NpuShmemPtr;
240	
241	    // 中转内存单次最多能够接受的output count，注意是count不是size
242	    u64 maxCountPerLoop = tempAlgParamsStepOne.buffInfo.hcclBuff.size / 2 / HCCL_MIN_SLICE_ALIGN * HCCL_MIN_SLICE_ALIGN
243	                          / dataTypeSize_; // 这边看前面有/10*10，不知道要不要加上
244	    // 计算loopTimes
245	    u64 loopTimes = dataCount_ / maxCountPerLoop + static_cast<u64>(dataCount_ % maxCountPerLoop != 0);
246	    u64 processedDataCount = 0;
247	    for (u64 loop = 0; loop < loopTimes; loop++) {
248	        u64 currDataCount = (loop == loopTimes - 1) ? dataCount_ - processedDataCount :
249	                                                      maxCountPerLoop; // 判断是最后一轮，就处理尾块长度
250	
251	        // ----------- 框内ReduceScatter数据搬运 -----------
252	        // 框内的数据偏移和搬运计算
253	        tempAlgParamsStepOne.count = currDataCount;
254	        tempAlgParamsStepOne.buffInfo.inBuffBaseOff = processedDataCount * dataTypeSize_;
255	        tempAlgParamsStepOne.buffInfo.outBuffBaseOff = 0;  // CCL-OUT
256	        tempAlgParamsStepOne.buffInfo.hcclBuffBaseOff = 0; // CCL-IN
257	        CHK_RET(
258	            SplitData(currDataCount, rankSizeLevel0_, tempAlgParamsStepOne)); // 计算每个卡对应位置的offset,count,size
259	        CHK_PRT_RET(
260	            tempAlgParamsStepOne.allRankSliceSize.size() != rankSizeLevel0_,
261	            HCCL_ERROR(
262	                "[InsV2AllReduceSequenceExecutor][tempAlgParamsStepOne] slice num[%u] is not equal to rank size[%u].",
263	                tempAlgParamsStepOne.allRankSliceSize.size(), rankSizeLevel0_),
264	            HcclResult::HCCL_E_INTERNAL);
265	        tempAlgParamsStepOne.sliceSize = 0; // 没用到，template里面用SplitData算了
266	        tempAlgParamsStepOne.tailSize = 0;  // 没用到
267	        // 这里的stride当成传统意义上的stride间隔
268	        tempAlgParamsStepOne.inputSliceStride = 0;  // 没用到
269	        tempAlgParamsStepOne.outputSliceStride = 0; // 没用到
270	
271	        HCCL_INFO(
272	            "[InsV2AllReduceSequenceExecutor] loop [%u] tempAlgParamsStepOne.inputSliceStride [%u],"
273	            "tempAlgParamsStepOne.outputSliceStride [%u] tempAlgParamsStepOne.sliceSize [%u]",
274	            loop, tempAlgParamsStepOne.inputSliceStride, tempAlgParamsStepOne.outputSliceStride,
275	            tempAlgParamsStepOne.sliceSize);
276	        HCCL_INFO(
277	            "[InsV2AllReduceSequenceExecutor] loop [%u] tempAlgParamsStepOne.buffInfo.inBuffBaseOff [%u],"
278	            "tempAlgParamsStepOne.buffInfo.outBuffBaseOff [%u]",
279	            loop, tempAlgParamsStepOne.buffInfo.inBuffBaseOff, tempAlgParamsStepOne.buffInfo.outBuffBaseOff);
280	        // 不需要重复
281	        tempAlgParamsStepOne.repeatNum = 1;
282	        tempAlgParamsStepOne.inputRepeatStride = 0;
283	        tempAlgParamsStepOne.outputRepeatStride = 0;
284	        // 因为只考虑执行0级算法，所以传进template里面的channels就是channels_的第一个vector
285	        CHK_RET(algTemplateStepOne->KernelRun(param, tempAlgParamsStepOne, templateResourceReduceScatterMesh1D));
286	
287	        // ----------- 框间ReduceScatterMesh1dDpu数据搬运 -----------
288	        // 框间的数据偏移和搬运量计算
289	        tempAlgParamsStepTwo.count = tempAlgParamsStepOne.allRankProcessedDataCount.at(rankIdxLevel0_);
290	        if (tempAlgParamsStepTwo.count != 0) { // 如果卡里没有数据，不参与框间，让该框有数据的其他卡参与跨框
291	            tempAlgParamsStepTwo.buffInfo.inBuffBaseOff = 0;   // ccl-out偏移量，每次更新，所以是0
292	            tempAlgParamsStepTwo.buffInfo.outBuffBaseOff = 0;  // ccl-out偏移量，每次更新，所以是0
293	            tempAlgParamsStepTwo.buffInfo.hcclBuffBaseOff = 0; // ccl-in
294	            tempAlgParamsStepTwo.sliceSize = 0;
295	            tempAlgParamsStepTwo.tailSize = 0;
296	            CHK_RET(SplitData(tempAlgParamsStepTwo.count, rankSizeLevel1_, tempAlgParamsStepTwo));
297	            CHK_PRT_RET(
298	                tempAlgParamsStepTwo.allRankSliceSize.size() != rankSizeLevel1_,
299	                HCCL_ERROR(
300	                    "[InsV2AllReduceSequenceExecutor][tempAlgParamsStepTwo] slice num[%u] is not "
301	                    "equal to rank size[%u].",
302	                    tempAlgParamsStepTwo.allRankSliceSize.size(), rankSizeLevel1_),
303	                HcclResult::HCCL_E_INTERNAL);
304	            // 这里的stride当成传统意义上的stride 间隔
305	            tempAlgParamsStepTwo.inputSliceStride = 0;  // 没用到
306	            tempAlgParamsStepTwo.outputSliceStride = 0; // 没用到
307	            //
308	            HCCL_INFO(
309	                "[InsV2AllReduceSequenceExecutor] loop [%u] tempAlgParamsStepTwo.inputSliceStride [%u],"
310	                "tempAlgParamsStepTwo.outputSliceStride [%u] "
311	                "tempAlgParamsStepTwo.sliceSize [%u]",
312	                loop, tempAlgParamsStepTwo.inputSliceStride, tempAlgParamsStepTwo.outputSliceStride,
313	                tempAlgParamsStepTwo.sliceSize);
314	            HCCL_INFO(
315	                "[InsV2AllReduceSequenceExecutor] loop [%u] "
316	                "tempAlgParamsStepTwo.buffInfo.inBuffBaseOff [%u],"
317	                "tempAlgParamsStepTwo.buffInfo.outBuffBaseOff [%u]",
318	                loop, tempAlgParamsStepTwo.buffInfo.inBuffBaseOff, tempAlgParamsStepTwo.buffInfo.outBuffBaseOff);
319	
320	            tempAlgParamsStepTwo.repeatNum = 1;
321	            tempAlgParamsStepTwo.inputRepeatStride = 0;
322	            tempAlgParamsStepTwo.outputRepeatStride = 0;
323	
324	            CHK_RET(algTemplateStepTwo->KernelRun(param, tempAlgParamsStepTwo, templateResourceReduceScatterMesh1dDpu));
325	        }
326	
327	        // ----------- 框间AllGatherNhr数据搬运 -----------
328	        // 框间的数据偏移和搬运量计算
329	        tempAlgParamsStepThree.count = tempAlgParamsStepOne.allRankProcessedDataCount.at(rankIdxLevel0_);
330	        if (tempAlgParamsStepTwo.count != 0) {
331	            tempAlgParamsStepThree.buffInfo.inBuffBaseOff = 0;   // ccl-out偏移量，每次更新，所以是0
332	            tempAlgParamsStepThree.buffInfo.outBuffBaseOff = 0;  // ccl-out偏移量，每次更新，所以是0
333	            tempAlgParamsStepThree.buffInfo.hcclBuffBaseOff = 0; // ccl-in
334	            tempAlgParamsStepThree.allRankDispls = tempAlgParamsStepTwo.allRankDispls;
335	            tempAlgParamsStepThree.allRankSliceSize = tempAlgParamsStepTwo.allRankSliceSize;
336	            tempAlgParamsStepThree.allRankProcessedDataCount = tempAlgParamsStepTwo.allRankProcessedDataCount;
337	
338	            tempAlgParamsStepThree.sliceSize = 0;
339	            tempAlgParamsStepThree.tailSize = 0;
340	            // 这里的stride当成传统意义上的stride 间隔
341	            tempAlgParamsStepThree.inputSliceStride = 0;
342	            tempAlgParamsStepThree.outputSliceStride = 0;
343	
344	            HCCL_INFO(
345	                "[InsV2AllReduceSequenceExecutor] loop [%u] tempAlgParamsStepThree.inputSliceStride [%u],"
346	                "tempAlgParamsStepThree.outputSliceStride [%u] tempAlgParamsStepThree.sliceSize [%u]",
347	                loop, tempAlgParamsStepThree.inputSliceStride, tempAlgParamsStepThree.outputSliceStride,
348	                tempAlgParamsStepThree.sliceSize);
349	            HCCL_INFO(
350	                "[InsV2AllReduceSequenceExecutor] loop [%u] tempAlgParamsStepThree.buffInfo.inBuffBaseOff [%u],"
351	                "tempAlgParamsStepThree.buffInfo.outBuffBaseOff [%u]",
352	                loop, tempAlgParamsStepThree.buffInfo.inBuffBaseOff, tempAlgParamsStepThree.buffInfo.outBuffBaseOff);
353	
354	            tempAlgParamsStepThree.repeatNum = 1;
355	            tempAlgParamsStepThree.inputRepeatStride = 0;
356	            tempAlgParamsStepThree.outputRepeatStride = 0;
357	
358	            CHK_RET(algTemplateStepThree->KernelRun(param, tempAlgParamsStepThree, templateResourceAllGatherNhrDPU));
359	        }
360	
361	        // ----------- 框内AllGatherMesh数据搬运 -----------
362	        // 框内的数据偏移和搬运计算
363	        tempAlgParamsStepFour.count = currDataCount;
364	        tempAlgParamsStepFour.buffInfo.inBuffBaseOff = 0;                                   // CCL-OUT
365	        tempAlgParamsStepFour.buffInfo.outBuffBaseOff = processedDataCount * dataTypeSize_; // USR-OUT
366	        tempAlgParamsStepFour.buffInfo.hcclBuffBaseOff = 0;                                 // CCL-IN
367	        tempAlgParamsStepFour.allRankDispls = tempAlgParamsStepOne.allRankDispls;
368	        tempAlgParamsStepFour.allRankSliceSize = tempAlgParamsStepOne.allRankSliceSize;
369	        tempAlgParamsStepFour.allRankProcessedDataCount = tempAlgParamsStepOne.allRankProcessedDataCount;
370	
371	        tempAlgParamsStepFour.sliceSize = 0;
372	        tempAlgParamsStepFour.tailSize = 0;
373	        // 这里的stride当成传统意义上的stride间隔
374	        tempAlgParamsStepFour.inputSliceStride = 0;
375	        tempAlgParamsStepFour.outputSliceStride = 0;
376	
377	        HCCL_INFO(
378	            "[InsV2AllReduceSequenceExecutor] loop [%u] tempAlgParamsStepFour.inputSliceStride [%u],"
379	            "tempAlgParamsStepFour.outputSliceStride [%u] tempAlgParamsStepFour.sliceSize [%u]",
380	            loop, tempAlgParamsStepFour.inputSliceStride, tempAlgParamsStepFour.outputSliceStride,
381	            tempAlgParamsStepFour.sliceSize);
382	        HCCL_INFO(
383	            "[InsV2AllReduceSequenceExecutor] loop [%u] tempAlgParamsStepFour.buffInfo.inBuffBaseOff [%u],"
384	            "tempAlgParamsStepFour.buffInfo.outBuffBaseOff [%u]",
385	            loop, tempAlgParamsStepFour.buffInfo.inBuffBaseOff, tempAlgParamsStepFour.buffInfo.outBuffBaseOff);
386	
387	        tempAlgParamsStepFour.repeatNum = 1;
388	        tempAlgParamsStepFour.inputRepeatStride = 0;
389	        tempAlgParamsStepFour.outputRepeatStride = 0;
390	
391	        CHK_RET(algTemplateStepFour->KernelRun(param, tempAlgParamsStepFour, templateResourceAllGatherMesh1D));
392	
393	        processedDataCount += currDataCount;
394	    }
395	    HCCL_INFO("[InsV2AllReduceSequenceExecutor][OrchestrateLoop] End.");
396	    return HCCL_SUCCESS;
397	}
398	
399	template <
400	    typename AlgTopoMatch, typename InsAlgTemplate0, typename InsAlgTemplate1, typename InsAlgTemplate2,
401	    typename InsAlgTemplate3>
402	u64 InsV2AllReduceSequenceExecutor<AlgTopoMatch, InsAlgTemplate0, InsAlgTemplate1, InsAlgTemplate2, InsAlgTemplate3>::
403	    RoundUp(const u64 dividend, const u64 divisor)
404	{
405	    if (divisor == 0) {
406	        HCCL_WARNING("[InsV2AllReduceSequenceExecutor][RoundUp] divisor is 0.");
407	        return dividend;
408	    }
409	    return (dividend + divisor - 1) / divisor;
410	}
411	
412	template <
413	    typename AlgTopoMatch, typename InsAlgTemplate0, typename InsAlgTemplate1, typename InsAlgTemplate2,
414	    typename InsAlgTemplate3>
415	HcclResult
416	InsV2AllReduceSequenceExecutor<AlgTopoMatch, InsAlgTemplate0, InsAlgTemplate1, InsAlgTemplate2, InsAlgTemplate3>::
417	    SplitData(const u64& dataCount, const uint64_t& rankSize, TemplateDataParams& tempAlgParams)
418	{
419	    u32 sliceNum = rankSize;
420	    tempAlgParams.allRankSliceSize.clear();
421	    tempAlgParams.allRankProcessedDataCount.clear();
422	    tempAlgParams.allRankDispls.clear();
423	    tempAlgParams.allRankSliceSize.reserve(sliceNum);
424	    tempAlgParams.allRankDispls.reserve(sliceNum);
425	    tempAlgParams.allRankProcessedDataCount.reserve(sliceNum);
426	
427	    u64 offsetCount = 0;
428	    u64 offsetSize = 0;
429	    u64 sliceCount = RoundUp(dataCount, sliceNum);
430	    u64 sliceSize = sliceCount * dataTypeSize_;
431	
432	    for (u32 sliceIdx = 0; sliceIdx < sliceNum; ++sliceIdx) {
433	        if (dataCount - offsetCount >= sliceCount) {
434	            tempAlgParams.allRankSliceSize.emplace_back(sliceSize);
435	            tempAlgParams.allRankProcessedDataCount.emplace_back(sliceCount);
436	            tempAlgParams.allRankDispls.emplace_back(offsetSize);
437	            offsetCount += sliceCount;
438	            offsetSize = offsetCount * dataTypeSize_;
439	        } else {
440	            u64 curSliceCount = dataCount - offsetCount;
441	            u64 curSliceSize = curSliceCount * dataTypeSize_;
442	            tempAlgParams.allRankSliceSize.emplace_back(curSliceSize);
443	            tempAlgParams.allRankProcessedDataCount.emplace_back(curSliceCount);
444	            tempAlgParams.allRankDispls.emplace_back(offsetSize);
445	            offsetCount = dataCount;
446	            offsetSize = offsetCount * dataTypeSize_;
447	        }
448	    }
449	
450	    for (u32 i = 0; i < tempAlgParams.allRankSliceSize.size(); ++i) {
451	        HCCL_DEBUG(
452	            "[InsV2AllReduceSequenceExecutor] SliceInfo: offset[%u] size[%u] count[%u]",
453	            tempAlgParams.allRankDispls.at(i), tempAlgParams.allRankSliceSize.at(i),
454	            tempAlgParams.allRankProcessedDataCount.at(i));
455	    }
456	
457	    return HcclResult::HCCL_SUCCESS;
458	}
459	
460	REGISTER_EXECUTOR_BY_FOUR_TEMPS(
461	    HcclCMDType::HCCL_CMD_ALLREDUCE, DpuAllReduceSequenceMeshNHR, InsV2AllReduceSequenceExecutor, TopoMatchMultilevel,
462	    InsTempReduceScatterMesh1DIntra, InsTempReduceScatterMesh1dDpuInter, InsTempAllGatherNhrDpuInter,
463	    InsTempAllGatherMesh1dIntra);
464	} // namespace ops_hccl
