137	HcclResult GetHcclDfxOpInfoDataCount(const OpParam& param, const u32& rankSize, uint64_t& sendCount)
138	{
139	    sendCount = 0;
140	    if (param.opType == HcclCMDType::HCCL_CMD_ALLTOALL) {
