386	HcclResult HcclAivCacheCheckAndReplay(HcclComm comm, OpParam& param, bool& cacheHit)
387	{
388	    cacheHit = false;
389	    if (!IsAivCacheSupported(param)) {
390	        return HCCL_SUCCESS;
391	    }
392	
393	    // 提前获取 numBlocksLimit，作为 cache key 的一部分
394	    // 与 HcclAivKernelEntranceLaunch 逻辑保持一致：先查 aivParam，再 fallback 到 runtime
395	    u32 numBlocksLimit = 0;
396	    AivParamStorage* aivParam = nullptr;
397	    HcclResult aivParamRet = GetAivParamStorageByComm(comm, &aivParam, false);
398	    if (aivParamRet == HCCL_SUCCESS && aivParam != nullptr) {
399	        numBlocksLimit = aivParam->aivCoreLimit;
400	    }
401	    if (numBlocksLimit == 0) {
402	        ACLCHECK(aclrtGetResInCurrentThread(ACL_RT_DEV_RES_VECTOR_CORE, &numBlocksLimit));
403	    }
404	    param.numBlocksLimit = numBlocksLimit;
405	
406	    AivOpCacheArgs cacheKey = {};
407	    cacheKey.commName = param.commName;
408	    cacheKey.opType = param.opType;
409	    cacheKey.root = param.root;
410	    cacheKey.reduceOp = param.reduceType;
411	    cacheKey.numBlocksLimit = numBlocksLimit;
412	    if (param.opType == HCCL_CMD_ALLTOALL) {
413	        cacheKey.dataType = param.all2AllVDataDes.sendType;
414	        cacheKey.count = static_cast<const u64*>(param.all2AllVDataDes.sendCounts)[0];
415	    } else if (param.opType == HCCL_CMD_ALLTOALLV) {
416	        cacheKey.dataType = param.all2AllVDataDes.sendType;
417	        cacheKey.count = 0; // counts 在 replay 时动态刷新,cache key 不区分
418	    } else {
419	        cacheKey.count = param.DataDes.count;
420	        cacheKey.dataType = param.DataDes.dataType;
421	    }
422	
423	    u64 keyHash = CalcAivCacheKeyHash(cacheKey);
424	    std::string ctxTag;
425	    CHK_RET(BuildAivCacheCtxTag(keyHash, ctxTag));
426	
427	    std::string cachedAlgName;
428	    AivInstruction* instructions = nullptr;
429	    u32 insCount = 0;
430	    CHK_RET(LookupAivCacheCtx(comm, ctxTag, keyHash, cacheHit, cachedAlgName, instructions, insCount));
431	    if (!cacheHit) {
432	        return HCCL_SUCCESS;
433	    }
434	
435	    HCCL_INFO("[HcclAivCacheCheckAndReplay] cache hit, algName[%s], insCount[%u]", cachedAlgName.c_str(), insCount);
436	
437	    int result = sprintf_s(param.algName, sizeof(param.algName), "%s", cachedAlgName.c_str());
438	    CHK_PRT_RET(result <= 0, HCCL_ERROR("[%s] failed to fill param.algName", __func__), HCCL_E_INTERNAL);
439	    CHK_RET(SetOpParamAlgTag(param, cachedAlgName));
440	    param.hcclComm = comm;
441	
442	    uint64_t beginTime = HcommGetProfilingSysCycleTime();
443	
444	    HcclDfxOpInfoCompat hcclDfxOpInfo{};
445	    CHK_RET(ConstructHcclDfxOpInfo(param, param.algTag, ALG_TAG_LENGTH, hcclDfxOpInfo, 0));
446	    param.dataCount = hcclDfxOpInfo.dataCount;
447	    CHK_RET(HcclDfxRegOpInfoByCommId(param.commName, reinterpret_cast<void*>(&hcclDfxOpInfo)));
448	
449	    if (param.opType == HCCL_CMD_ALLTOALLV) {
450	        CHK_RET(ReplayAivInstructionsV(instructions, insCount, param));
451	    } else {
452	        CHK_RET(ReplayAivInstructions(instructions, insCount, param));
453	    }
454	
455	    CHK_RET(HcclReportAivKernel(comm, beginTime));
456	    CHK_RET(HcclProfilingReportOp(comm, beginTime));
457	    return HCCL_SUCCESS;
458	}
