554	HcclResult FallbackOp(
555	    HcclComm comm, OpParam& param, std::unique_ptr<TopoInfoWithNetLayerDetails>& topoInfo, std::string& algName,
556	    const ResPackGraphMode& resPack)
557	{
558	    void* fallbackCtx = nullptr;
