561	    char* newAlgName = static_cast<char*>(fallbackCtx);
562	    CHK_RET(ReSelector(comm, param, topoInfo, algName));
563	    auto copyRet = sprintf_s(newAlgName, fallbackCtxSize, "%s", algName.c_str());
564	    if (copyRet <= 0) {
565	        HCCL_ERROR("[%s] failed to fill newAlgName", __func__);
566	        return HCCL_E_INTERNAL;
567	    }
568	    CHK_RET(HcclExecOp(comm, param, topoInfo, algName, resPack));
569	    return HCCL_SUCCESS;
570	}
