617	HcclResult HcclExecOp(
618	    HcclComm comm, OpParam& param, std::unique_ptr<TopoInfoWithNetLayerDetails>& topoInfo, std::string& algName,
619	    const ResPackGraphMode& resPack)
620	{
621	    uint64_t beginTime = HcommGetProfilingSysCycleTime();
622	    HCCL_INFO("[HcclExecOp]Start to execute HcclExecOp. HcommGetProfilingSysCycleTime[%llu]", beginTime);
623	    // 当前通信域的某个算法回退过，则下次直接回退
624	    void* fallbackCtx = nullptr;
625	    uint64_t fallbackCtxSize = 0;
626	    CHK_RET(SetOpParamFallbackTag(param, algName));
627	    if (HcclEngineCtxGet(comm, param.fallbackTag, param.engine, &fallbackCtx, &fallbackCtxSize) == HCCL_SUCCESS) {
628	        HCCL_INFO("[HcclExecOp] Engine ctx exists, try to fallback.");
629	        std::string newAlgName = static_cast<char*>(fallbackCtx);
630	        HCCL_INFO("[HcclExecOp] Cached algo type is %s.", newAlgName.c_str());
631	        param.opExecuteConfig = OpExecuteConfig::AICPU_TS;
632	        param.engine = COMM_ENGINE_AICPU_TS;
633	        CHK_RET(SetOpParamAlgTag(param, newAlgName));
634	        CHK_RET(HcclExecOp(comm, param, topoInfo, newAlgName, resPack));
635	        return HCCL_SUCCESS;
636	    }
637	    // 将算法名字放在param参数中
638	    int result = sprintf_s(param.algName, sizeof(param.algName), "%s", algName.c_str());
639	    if (result <= 0) {
640	        HCCL_ERROR("failed to fill param.algName");
641	        return HCCL_E_INTERNAL;
642	    }
643	    // 在原先的commName中添加执行模式，得到commModeTag
644	    param.hcclComm = comm;
645	    bool isOpBase = param.opMode == OpMode::OPBASE;
646	    const char* opModeStr = isOpBase ? "_opbase" : "_offload";
647	    auto ret = sprintf_s(param.commModeTag, sizeof(param.commModeTag), "%s_%s", param.commName, opModeStr);
648	    if (ret <= 0) {
649	        HCCL_ERROR("[%s] failed to fill param.commModeTag", __func__);
650	        return HCCL_E_INTERNAL;
651	    }
652	
653	    std::unique_ptr<InsCollAlgBase> executor = CollAlgExecRegistryV2::Instance().GetAlgExec(param.opType, algName);
654	    CHK_PRT_RET(
655	        executor.get() == nullptr, HCCL_ERROR("Fail to find executor for algName[%s]", algName.c_str()), HCCL_E_PARA);
656	
657	    // 资源结构体
658	    std::unique_ptr<AlgResourceCtxSerializable> resCtxHost = std::make_unique<AlgResourceCtxSerializable>();
659	    resCtxHost->isHcommBatchTransferOnThreadSupported = HcommIsSupportHcommBatchTransferOnThread();
660	    // 资源序列化结果
661	    void* resCtxSequence = nullptr;
662	    bool isResourceReused = false;
663	
664	    ThreadHandle cpuTsThread{0};
665	    ThreadHandle exportedAicpuTsThread{0};
666	    if ((param.engine == COMM_ENGINE_AICPU_TS) || (param.engine == COMM_ENGINE_CPU)) {
667	        CHK_RET(HcclThreadAcquireWithStream(comm, COMM_ENGINE_CPU_TS, param.stream, CPU_TS_NOTIFY_NUM, &cpuTsThread));
668	        // Export cpuTsThread
669	        CHK_RET(HcclThreadExportToCommEngine(comm, 1, &cpuTsThread, COMM_ENGINE_AICPU_TS, &exportedAicpuTsThread));
670	    }
671	
672	    auto resRet
673	        = HcclGetAlgRes(comm, param, executor, topoInfo.get(), resCtxHost, &resCtxSequence, isResourceReused, resPack);
674	    if (resRet == HCCL_E_UNAVAIL) {
675	        HCCL_WARNING("[HcclGetAlgRes] resource unavailable, try to fallback.");
676	        CHK_RET(FallbackOp(comm, param, topoInfo, algName, resPack));
677	        return HCCL_SUCCESS;
678	    } else {
679	        CHK_RET(resRet);
680	    }
681	
682	    param.cacheValid = isResourceReused;
683	
684	    // Op注册
685	    HcclDfxOpInfoCompat hcclDfxOpInfo{};
686	    CHK_RET(ConstructHcclDfxOpInfo(param, param.algTag, ALG_TAG_LENGTH, hcclDfxOpInfo, cpuTsThread));
687	    param.dataCount = hcclDfxOpInfo.dataCount;
688	    CHK_RET(HcclDfxRegOpInfoByCommId(param.commName, reinterpret_cast<void*>(&hcclDfxOpInfo)));
689	    ThreadHandle exportedCpuTsThread;
690	    ThreadHandle mainThread;
691	    u32 notifyNumOnMainThread;
692	    if ((param.engine == COMM_ENGINE_AICPU_TS) || (param.engine == COMM_ENGINE_CPU)) {
693	        // 获取主流信息
694	        CHK_RET(GetMainThreadInfo(comm, param, mainThread, notifyNumOnMainThread));
695	        // Export mainThread
696	        CHK_RET(HcclThreadExportToCommEngine(comm, 1, &mainThread, COMM_ENGINE_CPU_TS, &exportedCpuTsThread));
697	        // cpuTsThread 添加到param里
698	        param.opThread = exportedAicpuTsThread;
699	    }
700	
701	    // 算法执行
702	    if ((param.engine == COMM_ENGINE_AICPU_TS) || (param.engine == COMM_ENGINE_CPU)) {
703	        ThreadHandle unfoldThread;
704	        CHK_RET(GetUnfoldThreadInfo(comm, param, unfoldThread));
705	        // 根据主流的捕获状态决定展开流的状态
706	        CHK_RET(CaptureSlaveStreams(comm, param.stream, {mainThread, unfoldThread}, param.isCapture));
707	        // aicpu task cache使能
708	        param.aicpuCacheEnable = GetExternalInputHcclAicpuCacheEnable();
709	        CHK_RET(HcclAicpuKernelEntranceLaunch(
710	            comm, param, cpuTsThread, exportedCpuTsThread, notifyNumOnMainThread, resCtxSequence, algName,
711	            unfoldThread));
712	    } else if (param.engine == COMM_ENGINE_AIV) {
713	        uint64_t aivBeginTime = HcommGetProfilingSysCycleTime();
714	        param.resCtx = resCtxSequence;
715	        AlgResourceCtxSerializable& aivResCtxHost = *static_cast<AlgResourceCtxSerializable*>(resCtxSequence);
716	        CHK_RET(HcclAivKernelEntranceLaunch(comm, param, topoInfo, aivResCtxHost));
717	        CHK_RET(ExecuteAivCacheLogic(comm, param, algName, executor, aivResCtxHost));
718	        CHK_RET(HcclReportAivKernel(comm, aivBeginTime));
719	    } else if (param.engine == COMM_ENGINE_CCU) {
720	        if (isResourceReused) {
721	            // 复用资源，则需从engineCtx取得res，进行反序列化
722	            char* ctx = static_cast<char*>(resCtxSequence);
723	            std::vector<char> seq(ctx, ctx + param.ctxSize);
724	            resCtxHost->DeSerialize(seq);
725	            // 覆盖主流
726	            ThreadHandle thread;
727	            CHK_RET(HcclThreadAcquireWithStream(
728	                comm, param.engine, param.stream, resCtxHost->notifyNumOnMainThread, &thread));
729	            if (resCtxHost->threads.empty()) {
730	                HCCL_ERROR("[%s] reused threads is empty after DeSerialize, cannot overwrite main thread.", __func__);
731	                return HCCL_E_UNAVAIL;
732	            }
733	            resCtxHost->threads[0] = thread;
734	            // 图模式要全部覆盖
735	            if (param.opMode != OpMode::OPBASE) {
736	                CHK_RET(GeReuseResource(comm, param, executor, resCtxHost, topoInfo.get(), resPack));
737	            }
738	        }
739	        if (resCtxHost->slaveThreadNum > 0) {
740	            CHK_RET(CaptureSlaveStreams(comm, param.stream, resCtxHost->threads, param.isCapture));
741	        }
742	        CHK_RET(executor->Orchestrate(param, *resCtxHost));
743	    } else {
744	        if (isResourceReused) {
745	            // 复用资源，则需从engineCtx取得res，进行反序列化
746	            char* ctx = static_cast<char*>(resCtxSequence);
747	            std::vector<char> seq(ctx, ctx + param.ctxSize);
748	            resCtxHost->DeSerialize(seq);
749	        }
750	        CHK_RET(executor->Orchestrate(param, *resCtxHost));
751	    }
752	    // op上报
753	    CHK_RET(HcclProfilingReportOp(comm, beginTime));
754	    HCCL_INFO("Execute HcclExecOp success.");
755	    return HCCL_SUCCESS;
756	}
