758	HcclResult GeReuseResource(
759	    HcclComm comm, OpParam& param, std::unique_ptr<InsCollAlgBase>& executor,
760	    std::unique_ptr<AlgResourceCtxSerializable>& resCtxHost, TopoInfoWithNetLayerDetails* topoInfo,
761	    const ResPackGraphMode& resPack)
762	{
763	    // 计算AlgHierarchyInfo
764	    AlgHierarchyInfoForAllLevel algHierarchyInfo; // 分级通信域信息{localRankId, localRankSize}
765	    CHK_RET(executor->CalcAlgHierarchyInfo(comm, topoInfo, algHierarchyInfo));
766	    // 资源计算
767	    AlgResourceRequest resRequest;
768	    CHK_RET(executor->CalcRes(comm, param, topoInfo, algHierarchyInfo, resRequest));
769	
770	    u32 maxNotifyNum = 0;
771	    for (u32 i = 0; i < resRequest.notifyNumPerThread.size(); i++) {
772	        if (resRequest.notifyNumPerThread[i] > maxNotifyNum) {
773	            maxNotifyNum = resRequest.notifyNumPerThread[i];
774	        }
775	    }
776	
777	    u32 threadNum = resRequest.slaveThreadNum;
778	    u32 slaveStreams = resPack.streams.size();
779	    if (threadNum > slaveStreams) {
780	        HCCL_ERROR("[%s] threadNum[%u] exceeds slaveStreams[%u].", __func__, threadNum, slaveStreams);
781	        return HCCL_E_UNAVAIL;
782	    }
783	    if (resCtxHost->threads.size() < static_cast<size_t>(threadNum) + 1) {
784	        HCCL_ERROR(
785	            "[%s] reused threads size[%zu] is less than threadNum+1[%u].", __func__, resCtxHost->threads.size(),
786	            threadNum + 1);
787	        return HCCL_E_UNAVAIL;
788	    }
789	    for (u32 i = 0; i < threadNum; i++) {
790	        ThreadHandle slaveThread;
791	        CHK_RET(HcclThreadAcquireWithStream(comm, param.engine, resPack.streams[i], maxNotifyNum, &slaveThread));
792	        resCtxHost->threads[i + 1] = slaveThread;
793	    }
794	    return HCCL_SUCCESS;
795	}
