797	static HcclResult GetUnfoldStream(HcclComm comm, OpParam& param, ThreadHandle unfoldThread, aclrtStream& resolvedStream)
798	{
799	    void* unfoldStream = nullptr;
800	    auto& HcclThreadResGetInfoFunc = ops_hccl::DlHcommFunction::GetInstance();
801	    HcclResult ret;
802	    if (!HcclThreadResGetInfoFunc.dlHcclThreadResGetInfo || param.opMode == OpMode::OFFLOAD) { // 不走提前展开
803	        resolvedStream = param.stream;
804	    } else {
805	        ret = HcclThreadResGetInfoFunc.dlHcclThreadResGetInfo(comm, unfoldThread, 0, sizeof(void*), &unfoldStream);
806	        if (ret == HCCL_E_NOT_SUPPORT) {
807	            resolvedStream = param.stream;
808	        } else if (ret != HCCL_SUCCESS) {
809	            resolvedStream = param.stream;
810	            return ret;
811	        } else {
812	            resolvedStream = unfoldStream;
813	        }
814	    }
815	    return HCCL_SUCCESS;
816	}
