818	HcclResult HcclAicpuKernelEntranceLaunch(
819	    HcclComm comm, OpParam& param, ThreadHandle cpuTsThread, ThreadHandle exportedCpuTsThread,
820	    u32 notifyNumOnMainThread, void* resCtxSequence, std::string& algName, ThreadHandle unfoldThread)
821	{
822	    HCCL_DEBUG("[HcclAicpuKernelEntranceLaunch]start to run aicpu kernel");
823	    (void)algName;
824	    // 当前aicpu launch接口只能有一个输入参数，将Context指针放在param参数中
825	    param.resCtx = resCtxSequence;
826	    param.aicpuRecordCpuIdx = HOST_WAIT_AICPU_NOTIFYIDX;
827	
828	    if (param.engine == COMM_ENGINE_CPU) {
829	        // 注册dpu回调函数
830	        CHK_RET(static_cast<HcclResult>(HcclTaskRegister(comm, param.algTag, HcclLaunchDPUKernel)));
831	    }
832	
833	    if (HcommIsSupportHcclAicpuKernelLaunch()
834	        && (param.opType == HcclCMDType::HCCL_CMD_SEND || param.opType == HcclCMDType::HCCL_CMD_RECEIVE)) {
835	        HCCL_INFO(
836	            "[HcclAicpuKernelEntranceLaunch] P2P opType[%d], use HcclAicpuKernelLaunch",
837	            static_cast<int>(param.opType));
838	
839	        // 构造 HcclOpDesc
840	        HcclOpDesc opInfo;
841	
842	        CHK_SAFETY_FUNC_RET(memset_s(&opInfo, sizeof(HcclOpDesc), 0, sizeof(HcclOpDesc)));
843	        opInfo.opDescType = 1; // 1: P2P
844	
845	        std::string opNameStr = (param.opType == HcclCMDType::HCCL_CMD_SEND) ? "HcclSend" : "HcclRecv";
846	        CHK_SAFETY_FUNC_RET(
847	            strncpy_s(opInfo.opName, HCCL_OP_DESC_OP_NAME_MAX_LEN, opNameStr.c_str(), opNameStr.size()));
848	
849	        opInfo.p2p.buffer = (param.opType == HcclCMDType::HCCL_CMD_SEND) ? param.inputPtr : param.outputPtr;
850	        opInfo.p2p.cmdType = param.opType;
851	        opInfo.p2p.dataType = param.DataDes.dataType;
852	        opInfo.p2p.count = param.DataDes.count;
853	        opInfo.p2p.remoteRank = param.sendRecvRemoteRank;
854	        aclrtStream resolvedStream;
855	        (void)GetUnfoldStream(comm, param, unfoldThread, resolvedStream);
856	        HCCL_INFO("unfoldThread[%llu]", unfoldThread);
857	
858	        opInfo.p2p.unfoldStream = resolvedStream;
859	        // 构造 HcclKernelFuncInfo
860	        HcclKernelFuncInfo funcInfo;
861	        CHK_SAFETY_FUNC_RET(memset_s(&funcInfo, sizeof(HcclKernelFuncInfo), 0, sizeof(HcclKernelFuncInfo)));
862	
863	        int soRet = sprintf_s(funcInfo.kernelSoName, sizeof(funcInfo.kernelSoName), "libscatter_aicpu_kernel.so");
864	        CHK_PRT_RET(soRet <= 0, HCCL_ERROR("[%s] failed to fill kernelSoName", __func__), HCCL_E_INTERNAL);
865	
866	        int funcRet = sprintf_s(funcInfo.kernelFuncName, sizeof(funcInfo.kernelFuncName), "HcclLaunchP2pAicpuKernel");
867	        CHK_PRT_RET(funcRet <= 0, HCCL_ERROR("[%s] failed to fill kernelFuncName", __func__), HCCL_E_INTERNAL);
868	
869	        // 获取 aicpuThreadHandle
870	        ThreadHandle aicpuThreadHandle;
871	        u32 mainNotifyNum;
872	        CHK_RET(GetMainThreadInfo(comm, param, aicpuThreadHandle, mainNotifyNum));
873	
874	        // 调用 HcclAicpuKernelLaunch
875	        void* args = &param;
876	        uint32_t argSize = sizeof(OpParam) + param.varMemSize;
877	
878	        funcInfo.args = args;
879	        funcInfo.argSize = argSize;
880	
881	        HcclKernelLaunchCfg kernelLaunchCfg;
882	        AicpuTimeout timeout = DeriveAicpuTimeout(param.opConfig.execTimeout);
883	        u16 kernelLaunchTimeout
884	            = IsHcommDefaultTimeoutSupported() ?
885	                  timeout.kernelLaunchTimeout :
886	                  ToKernelLaunchTimeout(AddAicpuTimeoutOffset(param.opConfig.execTimeout, KERNEL_TIMEOUT_OFFSET));
887	        kernelLaunchCfg.timeOut = kernelLaunchTimeout;
888	
889	        CHK_RET(HcclAicpuKernelLaunch(comm, &opInfo, &funcInfo, aicpuThreadHandle, param.stream, &kernelLaunchCfg));
890	
891	        HCCL_INFO("[HcclAicpuKernelEntranceLaunch] P2P launch success, algTag[%s]", param.algTag);
892	        return HCCL_SUCCESS;
893	    }
894	
895	    // Host stream通知Device主thread，使用主流上idx最大的notify
896	    CHK_RET(static_cast<HcclResult>(
897	        HcommThreadNotifyRecordOnThread(cpuTsThread, exportedCpuTsThread, notifyNumOnMainThread - 1)));
898	
899	    // OrderLaunch第一阶段
900	    // 获取执行超时时间
901	    u32 execTimeout = ExecTimeoutManager::Instance().GetExecTimeout();
902	
903	    OrderLaunchMode launchMode = param.isCapture ?
904	                                     OrderLaunchMode::ORDER_LAUNCH_ACLGRAPH :
905	                                     (param.opMode == OpMode::OFFLOAD ? OrderLaunchMode::ORDER_LAUNCH_GE :
906	                                                                        OrderLaunchMode::ORDER_LAUNCH_OPBASE);
907	
908	    HcclRtEventGuard event0Guard;
909	    HcclRtEventGuard event1Guard;
910	    if (launchMode == OrderLaunchMode::ORDER_LAUNCH_ACLGRAPH) {
911	        CHK_RET(event0Guard.Create());
912	        CHK_RET(event1Guard.Create());
913	    }
914	    CHK_RET(HcclOrderLaunchToOrderStream(
915	        comm, param, unfoldThread, ORDER_UNFOLD_THREAD_NOTIFY_IDX, execTimeout, launchMode, event0Guard.Get()));
916	
917	    // AicpuKernel report
918	    uint64_t beginTime = HcommGetProfilingSysCycleTime();
919	    CHK_RET(AicpuKernelLaunch(comm, param, unfoldThread));
920	    CHK_PTR_NULL(comm);
921	
922	    // OrderLaunch第二阶段
923	    CHK_RET(HcclOrderLaunchToKernelStream(
924	        comm, unfoldThread, HOST_ORDER_THREAD_NOTIFY_IDX, execTimeout, launchMode, event1Guard.Get()));
925	
926	    std::string kernelName = "HcclLaunchAicpuKernel";
927	    char* kernelNameCStr = const_cast<char*>(kernelName.c_str());
928	    HcclResult ret = HcclReportAicpuKernel(comm, beginTime, kernelNameCStr);
929	    if (ret != HCCL_SUCCESS) {
930	        HCCL_ERROR(
931	            "[HcclAicpuKernelEntranceLaunch] HcclReportAicpuKernel failed, beginTime %lu, kernelNameCStr %s, ret %d ",
932	            beginTime, kernelNameCStr, ret);
933	        return ret;
934	    }
935	    // Host stream等待Device的通知
936	    AicpuTimeout timeout = DeriveAicpuTimeout(param.opConfig.execTimeout);
937	    u32 hostNotifyWaitTime = IsHcommDefaultTimeoutSupported() ?
938	                                 timeout.hostNotifyTimeout :
939	                                 AddAicpuTimeoutOffset(param.opConfig.execTimeout, HOST_NOTIFY_TIMEOUT_OFFSET);
940	    if (HcommIsSupportHcommSetNotifyWaitTimeOut()) {
941	        CHK_RET(HcclSetNotifyWaitTimeOut(hostNotifyWaitTime));
942	    }
943	    CHK_RET(HcclThreadNotifyWaitOnThreadDefault(cpuTsThread, param.aicpuRecordCpuIdx, hostNotifyWaitTime));
944	
945	    return HCCL_SUCCESS;
946	}
