948	HcclResult AicpuKernelLaunch(HcclComm comm, OpParam& param, ThreadHandle unfoldThread)
949	{
950	    std::string kernelName = "HcclLaunchAicpuKernel";
951	    aclrtFuncHandle funcHandle;
952	    aclrtArgsHandle argsHandle;
953	    // 注意，目前开源HCCL加载AICPU kernel使用的是从json文件加载
954	    // 详见load_kernel.cc中的LoadAICPUKernel函数，且只实现了scatter的，先共用scatter的
955	    aclError ret = aclrtBinaryGetFunction(g_binKernelHandle, kernelName.c_str(), &funcHandle);
956	    CHK_PRT_RET(
957	        ret != ACL_SUCCESS,
958	        HCCL_ERROR(
959	            "[aclrtBinaryGetFunction]errNo[0x%016llx] get func handle failed, "
960	            "kernelName:%s",
961	            ret, kernelName.c_str()),
962	        HCCL_E_RUNTIME);
963	    ret = aclrtKernelArgsInit(funcHandle, &argsHandle);
964	    CHK_PRT_RET(
965	        ret != ACL_SUCCESS,
966	        HCCL_ERROR(
967	            "[aclrtKernelArgsInit]errNo[0x%016llx] args init failed, "
968	            "kernelName:%s",
969	            ret, kernelName.c_str()),
970	        HCCL_E_RUNTIME);
971	    aclrtParamHandle paraHandle;
972	    size_t paramSize = sizeof(OpParam) + param.varMemSize;
973	    ret = aclrtKernelArgsAppend(argsHandle, &param, paramSize, &paraHandle);
974	    CHK_PRT_RET(
975	        ret != ACL_SUCCESS,
976	        HCCL_ERROR(
977	            "[aclrtKernelArgsAppend]errNo[0x%016llx] args append failed, append "
978	            "size %u, kernelName:%s",
979	            ret, paramSize, kernelName.c_str()),
980	        HCCL_E_RUNTIME);
981	    ret = aclrtKernelArgsFinalize(argsHandle);
982	    CHK_PRT_RET(
983	        ret != ACL_SUCCESS,
984	        HCCL_ERROR(
985	            "[aclrtKernelArgsFinalize]errNo[0x%016llx] args finalize failed, "
986	            "kernelName:%s",
987	            ret, kernelName.c_str()),
988	        HCCL_E_RUNTIME);
989	
990	    AicpuTimeout timeout = DeriveAicpuTimeout(param.opConfig.execTimeout);
991	    u16 kernelLaunchTimeout
992	        = IsHcommDefaultTimeoutSupported() ?
993	              timeout.kernelLaunchTimeout :
994	              ToKernelLaunchTimeout(AddAicpuTimeoutOffset(param.opConfig.execTimeout, KERNEL_TIMEOUT_OFFSET));
995	    aclrtLaunchKernelCfg cfg;
996	    aclrtLaunchKernelAttr attr;
997	    attr.id = ACL_RT_LAUNCH_KERNEL_ATTR_TIMEOUT;
998	    attr.value.timeout = kernelLaunchTimeout;
999	    cfg.numAttrs = 1;
1000	    cfg.attrs = &attr;
1001	    constexpr u32 numBlocks = 1;
1002	    HCCL_INFO("[AicpuKernelLaunch] unfoldThread [%lu]", unfoldThread); // 通过Thread获取展开流stream
1003	    void* unfoldStream = nullptr;
1004	    auto& HcclThreadResGetInfoFunc = ops_hccl::DlHcommFunction::GetInstance();
1005	    if (!HcclThreadResGetInfoFunc.dlHcclThreadResGetInfo || param.opMode == OpMode::OFFLOAD) { // 不走提前展开
1006	        ret = aclrtLaunchKernelWithConfig(funcHandle, numBlocks, param.stream, &cfg, argsHandle, nullptr);
1007	    } else {
1008	        HcclResult ret1
1009	            = HcclThreadResGetInfoFunc.dlHcclThreadResGetInfo(comm, unfoldThread, 0, sizeof(void*), &unfoldStream);
1010	        if (ret1 == HCCL_E_NOT_SUPPORT) {
1011	            ret = aclrtLaunchKernelWithConfig(funcHandle, numBlocks, param.stream, &cfg, argsHandle, nullptr);
1012	        } else if (ret1 != HCCL_SUCCESS) {
1013	            return ret1;
1014	        } else {
1015	            ret = aclrtLaunchKernelWithConfig(funcHandle, numBlocks, unfoldStream, &cfg, argsHandle, nullptr);
1016	        }
1017	    }
1018	    CHK_PRT_RET(
1019	        ret != ACL_SUCCESS,
1020	        HCCL_ERROR(
1021	            "[LoadCustomKernel][aclrtLaunchKernelWithConfig]"
1022	            "errNo[0x%016llx] launch kernel failed",
1023	            ret),
1024	        HCCL_E_OPEN_FILE_FAILURE);
1025	    return HCCL_SUCCESS;
1026	}
