1056	HcclResult
1057	CaptureSlaveStreams(HcclComm comm, aclrtStream mainStream, const std::vector<ThreadHandle>& threads, bool& isCapture)
1058	{
1059	    isCapture = false;
1060	    aclmdlRI rtModel = nullptr;
1061	    aclmdlRICaptureStatus captureStatus = aclmdlRICaptureStatus::ACL_MODEL_RI_CAPTURE_STATUS_NONE;
1062	    aclError ret = aclmdlRICaptureGetInfo(mainStream, &captureStatus, &rtModel);
1063	    if (ret == ACL_ERROR_RT_FEATURE_NOT_SUPPORT) {
1064	        HCCL_WARNING("[%s]Stream capture not support.", __func__);
1065	        return HCCL_SUCCESS;
1066	    } else {
1067	        CHK_PRT_RET(
1068	            ret != ACL_SUCCESS, HCCL_ERROR("[%s]aclmdlRICaptureGetInfo fail. return[%d].", __func__, ret),
1069	            HCCL_E_RUNTIME);
1070	    }
1071	    if (captureStatus != aclmdlRICaptureStatus::ACL_MODEL_RI_CAPTURE_STATUS_ACTIVE) {
1072	        HCCL_INFO("[%s]captureStatus is not active, captureStatus[%d]", __func__, captureStatus);
1073	        return HCCL_SUCCESS;
1074	    }
1075	    isCapture = true;
1076	    // thread[0] is main thread
1077	    auto& HcclThreadResGetInfoFunc = ops_hccl::DlHcommFunction::GetInstance();
1078	    for (size_t i = 1; i < threads.size(); ++i) {
1079	        void* stream = nullptr;
1080	        CHK_PRT_RET(
1081	            !HcclThreadResGetInfoFunc.dlHcclThreadResGetInfo, HCCL_ERROR("AclGraph is not support."),
1082	            HCCL_E_NOT_SUPPORT);
1083	        CHK_RET(HcclThreadResGetInfoFunc.dlHcclThreadResGetInfo(comm, threads[i], 0, sizeof(void*), &stream));
1084	        rtError_t addRet = rtStreamAddToModel(stream, rtModel);
1085	        CHK_PRT_RET(
1086	            addRet != RT_ERROR_NONE, HCCL_ERROR("[%s]rtStreamAddToModel fail. return[%d].", __func__, addRet),
1087	            HCCL_E_RUNTIME);
1088	        HCCL_DEBUG(
1089	            "[%s]add slaveStream to model success, idx[%zu], stream[%p], rtModel[%p]", __func__, i, stream, rtModel);
1090	    }
1091	    HCCL_INFO(
1092	        "[%s]success, captured streams to rtmodel:[%p], slaveStreamNum:[%zu]", __func__, rtModel,
1093	        threads.size() > 0 ? threads.size() - 1 : 0);
1094	    return HCCL_SUCCESS;
1095	}
