1257	    s32 sRet = strncpy_s(exchangeInfo.tag, TAG_LENGTH, param.tag, TAG_LENGTH);
1258	    CHK_PRT_RET(
1259	        sRet != EOK, HCCL_ERROR("[%s] call strncpy_s failed, param.tag[%s], return[%d].", __func__, param.tag, sRet),
1260	        HCCL_E_MEMORY);
1261	
1262	    HCCL_INFO(
1263	        "[%s] success. exchangeInfo dump: cclBufferSize[%llu], root[%u], opType[%u], opExecuteConfig[%u], "
1264	        "reduceType[%u], dataType[%u], count[%llu], aivCoreLimit[%u], group[%s], tag[%s]",
1265	        __func__, exchangeInfo.cclBufferSize, exchangeInfo.root, exchangeInfo.opType, exchangeInfo.opExecuteConfig,
1266	        exchangeInfo.reduceType, exchangeInfo.dataType, exchangeInfo.count, exchangeInfo.aivCoreLimit,
1267	        exchangeInfo.group, exchangeInfo.tag);
1268	    return HCCL_SUCCESS;
1269	}
