1443	HcclResult GetAlgResAICPU(
1444	    HcclComm comm, const OpParam& param, AlgResourceRequest& resRequest,
1445	    std::unique_ptr<AlgResourceCtxSerializable>& resCtxHost, TopoInfoWithNetLayerDetails* topoInfo,
1446	    AlgHierarchyInfoForAllLevel& algHierarchyInfo, void** resCtxSequence, uint64_t& ctxSize,
1447	    bool increCreateChannelFlag, const ResPackGraphMode& resPack)
1448	{
1449	    std::string hostCacheTag = std::string(param.algTag) + "_hostCache";
1450	    void* hostCtxPtr = nullptr;
1451	    uint64_t hostCtxSize = 0;
1452	    HcclResult hostCtxRet
1453	        = HcclEngineCtxGet(comm, hostCacheTag.c_str(), CommEngine::COMM_ENGINE_CPU_TS, &hostCtxPtr, &hostCtxSize);
1454	    if (!increCreateChannelFlag || hostCtxRet != HCCL_SUCCESS) {
1455	        resCtxHost->commInfoPtr = static_cast<void*>(comm);
1456	        resCtxHost->topoInfo = *topoInfo;
1457	        resCtxHost->algHierarchyInfo = algHierarchyInfo;
1458	        HcclResult ret = HcclAllocAlgResourceAICPU(comm, param, resRequest, resCtxHost, resPack);
1459	        CHK_PRT_RET(ret != HCCL_SUCCESS, HCCL_ERROR("failed to alloc alg resource."), ret);
1460	        std::vector<char> hostCtxSeq = resCtxHost->Serialize();
1461	        ret = HcclMemcpyCtxHostToDevice(comm, param, hostCtxSeq, resCtxSequence, ctxSize);
1462	        CHK_PRT_RET(ret != HCCL_SUCCESS, HCCL_ERROR("failed to memcpy hostCtx to device."), ret);
1463	        if (increCreateChannelFlag) {
1464	            CHK_RET(CacheHostCtxToEngine(comm, param.algTag, hostCacheTag, hostCtxSeq));
1465	        }
1466	    } else {
1467	        std::vector<char> cachedData(static_cast<char*>(hostCtxPtr), static_cast<char*>(hostCtxPtr) + hostCtxSize);
1468	        AlgResourceCtxSerializable hostCtxObj;
1469	        hostCtxObj.DeSerialize(cachedData);
1470	        CompReqChannelWithExistChannel(hostCtxObj.channels, resRequest);
1471	        if (resRequest.channels[0].size() == 0) {
1472	            return ReuseCachedDeviceCtx(comm, param, resCtxSequence, ctxSize);
1473	        }
1474	        CHK_RET(IncrementalCreateChannel(comm, param, resRequest, hostCtxObj, hostCacheTag, resCtxSequence, ctxSize));
1475	    }
1476	
1477	    HCCL_INFO("Execute GetAlgResAICPU success.");
1478	    return HCCL_SUCCESS;
1479	}
