1517	static HcclResult HcclGetThreadWithConfig(
1518	    HcclComm comm, const OpParam& param, AlgResourceRequest& resRequest, u32 threadNum,
1519	    std::vector<ThreadHandle>& threads, std::unique_ptr<AlgResourceCtxSerializable>& resCtxHost, bool unfoldReady)
1520	{
1521	    std::vector<ThreadConfig> threadConfigs(threadNum);
1522	    CHK_RET(static_cast<HcclResult>(ThreadConfigInit(threadConfigs.data(), threadNum)));
1523	    threadConfigs[0].notifyNumPerThread = resRequest.notifyNumOnMainThread + 1; // 主流上多一个用于host-device同步
1524	    HCCL_DEBUG("[HcclGetThread] AICPU thread[0] notify num[%u].", threadConfigs[0].notifyNumPerThread);
1525	    CHK_PRT_RET(
1526	        resRequest.notifyNumPerThread.size() < threadNum - 1,
1527	        HCCL_ERROR(
1528	            "[HcclGetThread] notifyNumPerThread size[%zu] is less than slaveThreadNum[%u].",
1529	            resRequest.notifyNumPerThread.size(), threadNum - 1),
1530	        HCCL_E_INTERNAL);
